/* Lab-only state machine for the E1/E2 (Layer 7) circuit. It DECIDES NOTHING: every decision is a lookup in fixtures.json,
 * generated by the audited Python harness over the real stimulus bytes. There is NO 'force send' action in this module. */
(function (root, factory) {
  if (typeof module === "object" && module.exports) module.exports = factory();
  else root.HFLab = factory();
})(typeof self !== "undefined" ? self : this, function () {
  "use strict";
  var EVENT_TYPES = ["trial_start", "preview_shown", "modality_selected", "send_attempt", "layer7_message_shown", "recovery_action", "send_simulated", "trial_end"];
  var RECOVERY_ACTIONS = ["change_modality", "replace_file"];
  var MODE = { A: "NOT_APPLICABLE_ARM_A", B: "SIMULATED_LAB_HARNESS_ONLY" };

  function createSession(options) {
    var fixtures = options.fixtures, arm = options.arm, lang = options.lang || "es";
    if (arm !== "A" && arm !== "B") throw new Error("arm must be A or B");
    if (["es", "pt", "en"].indexOf(lang) < 0) throw new Error("language must be es, pt or en");
    var trial = fixtures.trials.filter(function (t) { return t.stimulus_id === options.trialId; })[0];
    if (!trial) throw new Error("unknown trial");
    var clock = options.clock || function () { return 0; };
    var t0 = clock();
    var s = { arm: arm, lang: lang, trial: trial, modality: trial.initial_modality, fileId: "original", phase: "ready", events: [], blockedAt: null, sent: false };

    function log(type, payload) {
      if (EVENT_TYPES.indexOf(type) < 0) throw new Error("unknown event type " + type);
      var last = s.events.length ? s.events[s.events.length - 1].t_ms : 0;
      var now = Math.max(Math.round(clock() - t0), last);          // monotonic, relative milliseconds: never a calendar time
      var event = { type: type, t_ms: now };
      Object.keys(payload || {}).forEach(function (k) { event[k] = payload[k]; });
      s.events.push(event);
      return event;
    }
    function decision() {
      if (arm === "A") return { trigger_id: null, send_allowed: true, texts: null, message_id: null };      // legacy interface: no Layer 7
      var key = s.modality === null ? "none" : s.modality;
      return (s.fileId === "replacement" ? trial.replacement_by_modality : trial.by_modality)[key];
    }
    log("trial_start", { stimulus_id: trial.stimulus_id, scenario_code: trial.scenario_code, mechanism_id: "M2", arm: arm });
    if (arm === "B") log("preview_shown", {});
    var api = {
      state: function () { return { phase: s.phase, modality: s.modality, fileId: s.fileId, canSend: s.phase !== "blocked" && s.phase !== "sent", sent: s.sent }; },
      message: function () {
        var d = decision();
        return s.phase === "blocked" && d.trigger_id ? { trigger_id: d.trigger_id, message_id: d.message_id, text: d.texts[s.lang] } : null;
      },
      selectModality: function (option) {
        if (arm !== "B") throw new Error("arm A has no modality selector");
        if (fixtures.options.indexOf(option) < 0) throw new Error("unknown modality");
        if (s.sent) throw new Error("trial already sent");
        s.modality = option === "none" ? null : option;
        log("modality_selected", { modality: option });
        if (s.phase === "blocked") { log("recovery_action", { action: "change_modality", after_ms: Math.round(clock() - t0) - s.blockedAt }); s.phase = "ready"; }
      },
      replaceFile: function () {
        if (s.phase !== "blocked") throw new Error("replace_file is a recovery action: it needs a blocked state");
        s.fileId = "replacement";
        log("recovery_action", { action: "replace_file", after_ms: Math.round(clock() - t0) - s.blockedAt });
        s.phase = "ready";
      },
      attemptSend: function () {
        if (s.sent) throw new Error("trial already sent");
        if (s.phase === "blocked") throw new Error("send is not available while Layer 7 holds the file (no force send)");
        log("send_attempt", {});
        var d = decision();
        if (arm === "B" && d.trigger_id) {
          s.phase = "blocked"; s.blockedAt = Math.round(clock() - t0);
          log("layer7_message_shown", { trigger_id: d.trigger_id, message_id: d.message_id, send_allowed: false });
          return { blocked: true, trigger_id: d.trigger_id, text: d.texts[s.lang] };
        }
        s.sent = true; s.phase = "sent";
        log("send_simulated", { layer7_trigger_code: null });
        return { blocked: false };
      },
      finish: function () {
        var outcome = s.sent ? "completed" : (s.phase === "blocked" ? "blocked_by_layer7" : "abandoned");
        var recovered = s.events.some(function (e) { return e.type === "recovery_action"; });
        log("trial_end", { outcome_status: outcome, recovery_outcome: recovered ? "recovered" : (arm === "B" && s.blockedAt !== null ? "not_recovered" : "not_applicable") });
        return api.export();
      },
      export: function () {
        return { ui_version: "ui-0.1", label: "SIMULATED_LAYER7_HARNESS_LAB_ONLY", layer7_execution_mode: MODE[arm], arm: arm, mechanism_id: "M2",
                 stimulus_id: trial.stimulus_id, events: s.events.slice(), forced_send_available: false };
      }
    };
    return api;
  }
  return { createSession: createSession, EVENT_TYPES: EVENT_TYPES, RECOVERY_ACTIONS: RECOVERY_ACTIONS };
});
